def f(g):
    M=max(max(r) for r in g); h=len(g); w=len(g[0])
    v0=list(g[0])
    # fill row0 zeros: propagate from left (left+1 mod M), handle leading zeros from right
    for j in range(w):
        if v0[j]==0:
            v0[j]= (v0[j-1]%M)+1 if j>0 else None
    if v0[0]==0:
        for j in range(w-1,-1,-1):
            if v0[j]==0:
                v0[j]= ((v0[j+1]-2)%M)+1 if j+1<w else None
            else: break
    return [[v0[(j+1)%w] if j<i else v0[j%w] for j in range(w)] for i in range(h)]
